1	package stowage
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	)
8	
9	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
10	//
11	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
12	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
13	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
14	// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
15	// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
16	// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
17	// 参与比较。
18	//
19	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
20	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
21	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
22	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
23	// 范围也会被拒绝。
24	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
25		r.mu.Lock()
26		defer r.mu.Unlock()
27	
28		aid := strings.TrimSpace(adjustmentID)
29		if aid == "" {
30			return nil, fail(ErrInvalidID, "", "调整编号为空")
31		}
32	
33		// f 构造带调整编号的错误。
34		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
35			e := fail(kind, id, format, args...)
36			e.AdjustmentID = aid
37			return e
38		}
39	
40		// 幂等：编号已成功使用过。
41		if saved, ok := r.adjustments[aid]; ok {
42			if r.contents[aid] == canonicalKey(ops) {
43				return cloneResult(saved), nil
44			}
45			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
46		}
47	
48		if len(ops) == 0 {
49			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
50		}
51	
52		vops, final, affected, err := r.prepareOps(ops, f)
53		if err != nil {
54			return nil, err
55		}
56	
57		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整；
58		// 拒绝原因到结构化错误的转换与 AmendCargo 共用。
59		if rej := r.firstRejection(final); rej != nil {
60			return nil, rejectionError(rej, f)
61		}
62	
63		// 全部合法，正式生效。先计算受影响舱位调整前后的重量；前后配载都
64		// 经过重量校验（原配载由历次成功操作累积而成，最终配载刚通过检查），
65		// 合计必然可以用 int64 表示。
66		cargoChanges := make([]CargoChange, 0, len(vops))
67		compChanges := make([]CompartmentChange, 0, len(affected))
68		for id := range affected {
69			before, _ := weightTotal(r.compartments[id].cargo)
70			after, _ := weightTotal(final[id])
71			compChanges = append(compChanges, CompartmentChange{
72				CompartmentID: id,
73				WeightBefore:  before,
74				WeightAfter:   after,
75			})
76		}
77		sort.Slice(compChanges, func(i, j int) bool {
78			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
79		})
80	
81		for _, v := range vops {
82			c := v.cargo
83			// 正式生效的落点与预演模拟共用 relocate，去向沿用逐条校验时由
84			// routeFor 确定的同一份 from/to，因此生效结果与预览逐件对应。
85			relocate(c, v.rt, r.cargoSet(v.rt.from), r.cargoSet(v.rt.to))
86			c.compartmentID = v.rt.to
87			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: v.rt.from, To: v.rt.to})
88		}
89		sort.Slice(cargoChanges, func(i, j int) bool {
90			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
91		})
92	
93		result := &AdjustmentResult{
94			ID:                 aid,
95			CargoChanges:       cargoChanges,
96			CompartmentChanges: compChanges,
97		}
98		r.adjustments[aid] = result
99		r.contents[aid] = canonicalKey(ops)
100		return cloneResult(result), nil
101	}
102	
103	// validOp 是一条通过逐条校验的操作，附带其涉及的货物与由 routeFor
104	// 确定的去向。落点与变化记录只需货物和去向，原始操作与目标舱位在逐条
105	// 校验完成后不再需要。
106	type validOp struct {
107		cargo *cargo
108		rt    cargoRoute // 由 routeFor 确定的原舱位与最终舱位
109	}
110	
111	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
112	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
113	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
114	// 目标舱位（交换中的两个舱位都会纳入）。
115	func (r *Registry) prepareOps(
116		ops []Op,
117		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
118	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
119		seen := make(map[string]bool)
120		vops = make([]validOp, 0, len(ops))
121		affected = make(map[string]bool)
122	
123		for _, op := range ops {
124			cid := strings.TrimSpace(op.CargoID)
125			if cid == "" {
126				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
127			}
128			c, ok := r.cargos[cid]
129			if !ok {
130				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
131			}
132			if seen[cid] {
133				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
134			}
135			seen[cid] = true
136	
137			// 逐条校验，确定操作种类与目标舱位；通过后由 routeFor 统一
138			// 固定去向，模拟落点、预览变化记录与正式生效共用这同一份去向。
139			var target *compartment
140			switch op.Kind {
141			case OpLoad:
142				if c.compartmentID != "" {
143					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
144				}
145				tid := strings.TrimSpace(op.Target)
146				if tid == "" {
147					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
148				}
149				t, ok := r.compartments[tid]
150				if !ok {
151					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
152				}
153				target = t
154			case OpUnload:
155				if c.compartmentID == "" {
156					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
157				}
158				// 卸下忽略目标值，target 保持 nil。
159			case OpMove:
160				if c.compartmentID == "" {
161					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
162				}
163				tid := strings.TrimSpace(op.Target)
164				if tid == "" {
165					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
166				}
167				t, ok := r.compartments[tid]
168				if !ok {
169					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
170				}
171				if t.id == c.compartmentID {
172					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
173				}
174				target = t
175			default:
176				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
177			}
178	
179			rt := routeFor(op.Kind, c.compartmentID, target)
180			vops = append(vops, validOp{cargo: c, rt: rt})
181			touchedCompartments(affected, rt)
182		}
183	
184		// 在模拟配载上应用全部操作，落点与正式生效共用 relocate，判断以
185		// 完成后的最终状态为准。
186		final = make(map[string]map[string]*cargo, len(r.compartments))
187		for id, comp := range r.compartments {
188			set := make(map[string]*cargo, len(comp.cargo))
189			for cid, c := range comp.cargo {
190				set[cid] = c
191			}
192			final[id] = set
193		}
194		for _, v := range vops {
195			relocate(v.cargo, v.rt, final[v.rt.from], final[v.rt.to])
196		}
197		return vops, final, affected, nil
198	}
199	
200	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
201	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
202	// 调用方必须持有 r.mu。
203	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
204		var rejs []*Rejection
205		for id, set := range final {
206			comp := r.compartments[id]
207	
208			// 重量原因：合计规则与快照共用同一入口；溢出优先，溢出时不提供
209			// 任何重量数值。
210			sum, ok := weightTotal(set)
211			var rej *Rejection
212			if !ok {
213				rej = &Rejection{
214					CompartmentID: id,
215					Kind:          ErrOverflow,
216					MaxWeight:     comp.maxWeight,
217				}
218			} else if sum > comp.maxWeight {
219				rej = &Rejection{
220					CompartmentID:   id,
221					Kind:            ErrOverweight,
222					MaxWeight:       comp.maxWeight,
223					UsedWeight:      sum,
224					RemainingWeight: comp.maxWeight - sum,
225					Overweight:      sum - comp.maxWeight,
226				}
227			}
228	
229			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
230			destinations := make(map[string][]string)
231			destSet := make(map[string]bool)
232			var offenders []string
233			for _, c := range set {
234				destinations[c.destination] = append(destinations[c.destination], c.id)
235				destSet[c.destination] = true
236				if !c.allowMixed {
237					offenders = append(offenders, c.id)
238				}
239			}
240			if len(destSet) > 1 && len(offenders) > 0 {
241				dests := make([]MixedDestination, 0, len(destinations))
242				for dest, ids := range destinations {
243					sorted := append([]string(nil), ids...)
244					sort.Strings(sorted)
245					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
246				}
247				sort.Slice(dests, func(i, j int) bool {
248					return dests[i].Destination < dests[j].Destination
249				})
250				sort.Strings(offenders)
251				mr := &Rejection{
252					CompartmentID:  id,
253					Kind:           ErrMixedLoading,
254					MaxWeight:      comp.maxWeight,
255					Destinations:   dests,
256					OffendingCargo: offenders,
257				}
258				if rej != nil {
259					rejs = append(rejs, rej, mr)
260				} else {
261					rejs = append(rejs, mr)
262				}
263			} else if rej != nil {
264				rejs = append(rejs, rej)
265			}
266		}
267		return rejs
268	}
269	
270	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
271	// 调用方必须持有 r.mu。
272	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
273		rejs := r.evaluateFinal(final)
274		if len(rejs) == 0 {
275			return nil
276		}
277		sort.Slice(rejs, func(i, j int) bool {
278			if rejs[i].CompartmentID != rejs[j].CompartmentID {
279				return rejs[i].CompartmentID < rejs[j].CompartmentID
280			}
281			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
282		})
283		return rejs[0]
284	}
285	
286	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
287	func rejKindOrder(k ErrorKind) int {
288		switch k {
289		case ErrOverflow, ErrOverweight:
290			return 0
291		default:
292			return 1
293		}
294	}
295	
296	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
297	func (x *Rejection) firstOffender() string {
298		if len(x.OffendingCargo) == 0 {
299			return ""
300		}
301		return x.OffendingCargo[0]
302	}
303	
304	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
305	// 即视为相同内容，排列顺序不影响判断。卸下操作忽略目标舱位（执行时
306	// 同样忽略），其目标值不影响内容判断；装载与移动的目标舱位参与比较。
307	// 编号按去掉首尾空白后的原始字节精确比较：任何字节差异都视为不同内容，
308	// 包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD 的编号也不相同。
309	func canonicalKey(ops []Op) string {
310		sorted := make([]Op, len(ops))
311		for i, op := range ops {
312			target := strings.TrimSpace(op.Target)
313			if op.Kind == OpUnload {
314				target = ""
315			}
316			sorted[i] = Op{
317				Kind:    op.Kind,
318				CargoID: strings.TrimSpace(op.CargoID),
319				Target:  target,
320			}
321		}
322		sort.Slice(sorted, func(i, j int) bool {
323			if sorted[i].Kind != sorted[j].Kind {
324				return sorted[i].Kind < sorted[j].Kind
325			}
326			if sorted[i].CargoID != sorted[j].CargoID {
327				return sorted[i].CargoID < sorted[j].CargoID
328			}
329			return sorted[i].Target < sorted[j].Target
330		})
331		// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
332		// 任意字节内容都不会因分隔符或转义而碰撞。
333		var b strings.Builder
334		for _, op := range sorted {
335			b.WriteString(strconv.Itoa(int(op.Kind)))
336			b.WriteByte('|')
337			writeRawField(&b, op.CargoID)
338			writeRawField(&b, op.Target)
339		}
340		return b.String()
341	}
342	
343	// writeRawField 以“长度:原始字节”的形式写入一个字段。
344	func writeRawField(b *strings.Builder, s string) {
345		b.WriteString(strconv.Itoa(len(s)))
346		b.WriteByte(':')
347		b.WriteString(s)
348	}
349

