39			cargos:       make(map[string]*cargo),
40			adjustments:  make(map[string]*AdjustmentResult),
41			contents:     make(map[string]string),
42		}
43	}
44	
45	// RegisterCompartment 登记一个舱位。
46	// 编号去掉首尾空白后不得为空，maxWeight 必须为正整数（千克）。
47	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
48	func (r *Registry) RegisterCompartment(id string, maxWeight int64) error {
49		r.mu.Lock()
50		defer r.mu.Unlock()
51	
52		cid := strings.TrimSpace(id)
53		if cid == "" {
54			return fail(ErrInvalidID, "", "舱位编号为空")
55		}
56		if maxWeight <= 0 {
57			return fail(ErrInvalidWeight, cid, "舱位 %s 最大承重必须为正整数千克，当前为 %d", cid, maxWeight)
58		}
59		if _, exists := r.compartments[cid]; exists {
60			return fail(ErrAlreadyExists, cid, "舱位 %s 已存在", cid)
61		}
62		r.compartments[cid] = &compartment{
63			id:        cid,
64			maxWeight: maxWeight,
65			cargo:     make(map[string]*cargo),
66		}
67		return nil
68	}
69	
70	// RegisterCargo 登记一件货物。
71	// 编号与目的地去掉首尾空白后不得为空，weight 必须为正整数（千克）。
72	// 货物登记后处于未装载状态。
73	// 编号按去空白后的值识别并区分大小写；重复登记保留原记录。
74	func (r *Registry) RegisterCargo(id string, weight int64, destination string, allowMixed bool) error {
75		r.mu.Lock()
76		defer r.mu.Unlock()
77	
78		cid := strings.TrimSpace(id)
79		if cid == "" {
80			return fail(ErrInvalidID, "", "货物编号为空")
81		}
82		if weight <= 0 {
83			return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
84		}
85		dest := strings.TrimSpace(destination)
86		if dest == "" {
87			return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
88		}
89		if _, exists := r.cargos[cid]; exists {
90			return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
91		}
92		r.cargos[cid] = &cargo{
93			id:          cid,
94			weight:      weight,
95			destination: dest,
96			allowMixed:  allowMixed,
97		}
98		return nil
99	}
100	
101	// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
102	// 编号去掉首尾空白后识别；不存在时返回错误。
103	func (r *Registry) Compartment(id string) (*CompartmentView, error) {
104		r.mu.Lock()
105		defer r.mu.Unlock()
106	
107		cid := strings.TrimSpace(id)
108		if cid == "" {
109			return nil, fail(ErrInvalidID, "", "舱位编号为空")
110		}
111		comp, ok := r.compartments[cid]
112		if !ok {
113			return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
114		}
115		view := compartmentView(comp)
116		return &view, nil
117	}
118	
119	// Cargo 查询货物的当前舱位或未装载状态。
120	// 编号去掉首尾空白后识别；不存在时返回错误。
121	func (r *Registry) Cargo(id string) (*CargoView, error) {
122		r.mu.Lock()
123		defer r.mu.Unlock()
124	
125		cid := strings.TrimSpace(id)
126		if cid == "" {
127			return nil, fail(ErrInvalidID, "", "货物编号为空")
128		}
129		c, ok := r.cargos[cid]
130		if !ok {
131			return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
132		}
133		return cargoView(c), nil
134	}
135	
136	// cloneResult 复制一份调整结果，避免调用方修改影响已保存的快照。
137	func cloneResult(r *AdjustmentResult) *AdjustmentResult {
138		return &AdjustmentResult{
139			ID:                 r.ID,
140			CargoChanges:       append([]CargoChange(nil), r.CargoChanges...),
141			CompartmentChanges: append([]CompartmentChange(nil), r.CompartmentChanges...),
142		}
143	}
